"use client";

import Visibility from "@mui/icons-material/Visibility";
import VisibilityOff from "@mui/icons-material/VisibilityOff";
import {
  Box,
  Button,
  Card,
  CardContent,
  CircularProgress,
  IconButton,
  InputAdornment,
  TextField,
  Typography
} from "@mui/material";
import { Controller, SubmitHandler, useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import { useState } from "react";
import { useRouter } from "next/navigation";

type LoginFormValues = {
  userId: string;
  password: string;
};

const clsLoginSchema: yup.ObjectSchema<LoginFormValues> = yup.object({
  userId: yup
    .string()
    .required("User ID is required.")
    .min(4, "User ID must be at least 4 characters."),
  password: yup
    .string()
    .required("Password is required.")
    .min(6, "Password must be at least 6 characters.")
});

// Renders the modern login page with schema-based validation and submit feedback.
export default function LoginPage() {
  // Functional responsibility:
  // - Render login UI and validate credentials using React Hook Form + Yup.
  // Inputs:
  // - User-provided userId and password values.
  // Output:
  // - Validated submit flow with loading state and success alert.
  // Failure behavior:
  // - Invalid form blocks submission and displays field-level errors.
  const [isPasswordVisible, setIsPasswordVisible] = useState(false);
  const router = useRouter();

  const {
    control,
    handleSubmit,
    formState: { errors, isValid, isSubmitting }
  } = useForm<LoginFormValues>({
    mode: "onChange",
    resolver: yupResolver(clsLoginSchema),
    defaultValues: {
      userId: "",
      password: ""
    }
  });

  const onSubmit: SubmitHandler<LoginFormValues> = async (dicFormData) => {
    console.log("Login Form Data:", dicFormData);

    await new Promise<void>((resolve) => {
      setTimeout(() => {
        resolve();
      }, 2000);
    });

    const strAuthCookie = "hrms_auth=1; Path=/; Max-Age=28800; SameSite=Lax";
    document.cookie = strAuthCookie;
    router.push("/dashboard");
  };

  return (
    <Box
      sx={{
        minHeight: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        px: 2,
        backgroundColor: "#f4f7fb"
      }}
    >
      <Card elevation={8} sx={{ width: "100%", maxWidth: 420, borderRadius: 3 }}>
        <CardContent sx={{ p: 3 }}>
          <Typography variant="h5" fontWeight={700} sx={{ mb: 0.5 }}>
            Sign In
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2.5 }}>
            Welcome back. Please login to continue.
          </Typography>

          <Box component="form" onSubmit={handleSubmit(onSubmit)} noValidate>
            <Controller
              name="userId"
              control={control}
              render={({ field }) => (
                <TextField
                  {...field}
                  id="login-user-id"
                  label="User ID"
                  fullWidth
                  required
                  autoFocus
                  margin="normal"
                  error={Boolean(errors.userId)}
                  helperText={errors.userId?.message}
                  inputProps={{ "aria-label": "User ID input", minLength: 4 }}
                />
              )}
            />

            <Controller
              name="password"
              control={control}
              render={({ field }) => (
                <TextField
                  {...field}
                  id="login-password"
                  label="Password"
                  type={isPasswordVisible ? "text" : "password"}
                  fullWidth
                  required
                  margin="normal"
                  error={Boolean(errors.password)}
                  helperText={errors.password?.message}
                  inputProps={{ "aria-label": "Password input", minLength: 6 }}
                  InputProps={{
                    endAdornment: (
                      <InputAdornment position="end">
                        <IconButton
                          onClick={() => setIsPasswordVisible((prev) => !prev)}
                          edge="end"
                          aria-label={isPasswordVisible ? "Hide password" : "Show password"}
                          aria-controls="login-password"
                        >
                          {isPasswordVisible ? <VisibilityOff /> : <Visibility />}
                        </IconButton>
                      </InputAdornment>
                    )
                  }}
                />
              )}
            />

            <Button
              type="submit"
              fullWidth
              variant="contained"
              disabled={!isValid || isSubmitting}
              sx={{ mt: 2, py: 1.2 }}
              aria-busy={isSubmitting}
            >
              {isSubmitting ? <CircularProgress size={22} color="inherit" /> : "Login"}
            </Button>
          </Box>
        </CardContent>
      </Card>
    </Box>
  );
}
